+/**
+ * Length of the strings `array.join(',')` would build from the elements
+ * (nullish elements are empty, nested arrays join with ","), computed without
+ * allocating them. Stops once the running total passes `budget`, so a nested
+ * or shared-reference structure cannot cost more than the cap.
+ */
+function stringifiedSize(array: unknown[], budget: number): number {
+	let size = 0;
+	for (const element of array) {
+		if (size > budget) break;
+		if (element === null || element === undefined) continue;
+		if (isArray(element)) {
+			size += element.length > 0 ? element.length - 1 : 0;
+			size += stringifiedSize(element, budget - size);
+		} else {
+			size += toStr(element).length;
+		}
+	}
+	return size;
+}
